using System.Net.Mail;using System.Text.RegularExpressions;using SchoolERP.Domain.Common;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Events;using SchoolERP.Domain.Exceptions;using SchoolERP.Domain.Interfaces;
namespace SchoolERP.Domain.Entities;
public sealed partial class Department:AuditableEntity,ITenantEntity,IAggregateRoot{
 private string _name="",_code="";private Department(){} public Guid TenantId{get;private set;} public Guid SchoolId{get;private set;} public Guid? CampusId{get;private set;} public string Name{get=>_name;private set=>_name=Required(value,150,nameof(Name));} public string Code{get=>_code;private set=>_code=NormalizeCode(value);} public string? ShortName{get;private set;} public DepartmentType Type{get;private set;} public int DisplayOrder{get;private set;} public string? HeadName{get;private set;} public string? Email{get;private set;} public string? Phone{get;private set;} public string? Location{get;private set;} public DepartmentStatus Status{get;private set;}=DepartmentStatus.Draft; public string? Description{get;private set;} public DateTime? ActivatedAt{get;private set;} public DateTime? DeactivatedAt{get;private set;} public DateTime? ArchivedAt{get;private set;} public Tenant Tenant{get;private set;}=null!; public School School{get;private set;}=null!; public Campus? Campus{get;private set;}
 Guid ITenantEntity.TenantId{get=>TenantId;set{if(TenantId!=Guid.Empty&&TenantId!=value)throw new DomainException("Department tenant cannot change.");TenantId=value;}}
 public static Department Create(Guid tenantId,Guid schoolId,Guid? campusId,string name,string code,DepartmentType type,int displayOrder,string? headName=null,string? email=null,string? phone=null,string? location=null,string? description=null,string? shortName=null,DateTime? now=null){if(tenantId==Guid.Empty||schoolId==Guid.Empty)throw new DomainException("Department ownership is required.");var x=new Department{TenantId=tenantId,SchoolId=schoolId,CampusId=campusId,Name=name,Code=code};x.UpdateCore(name,shortName,type,displayOrder,headName,email,phone,location,description);x.AddDomainEvent(new DepartmentCreatedDomainEvent(x.Id,schoolId,campusId,tenantId,U(now??DateTime.UtcNow)));return x;}
 public void UpdateDetails(string name,string? shortName,DepartmentType type,int displayOrder,string? headName,string? email,string? phone,string? location,string? description,DateTime now){Writable();UpdateCore(name,shortName,type,displayOrder,headName,email,phone,location,description);AddDomainEvent(new DepartmentUpdatedDomainEvent(Id,SchoolId,CampusId,TenantId,U(now)));}
 public void ChangeCode(string code,DateTime now){if(Status!=DepartmentStatus.Draft)throw new DomainException("Department code can only change while Draft.");Code=code;AddDomainEvent(new DepartmentCodeChangedDomainEvent(Id,SchoolId,CampusId,TenantId,U(now)));}
 public void Activate(DateTime now){if(Status is not(DepartmentStatus.Draft or DepartmentStatus.Inactive))throw new DomainException("Only Draft or Inactive departments can activate.");Status=DepartmentStatus.Active;ActivatedAt??=U(now);DeactivatedAt=null;AddDomainEvent(new DepartmentActivatedDomainEvent(Id,SchoolId,CampusId,TenantId,U(now)));}
 public void Deactivate(DateTime now){if(Status!=DepartmentStatus.Active)throw new DomainException("Only Active departments can deactivate.");Status=DepartmentStatus.Inactive;DeactivatedAt=U(now);AddDomainEvent(new DepartmentDeactivatedDomainEvent(Id,SchoolId,CampusId,TenantId,U(now)));}
 public void Archive(DateTime now){if(Status is not(DepartmentStatus.Draft or DepartmentStatus.Inactive))throw new DomainException("Deactivate an Active department before archiving.");Status=DepartmentStatus.Archived;ArchivedAt=U(now);AddDomainEvent(new DepartmentArchivedDomainEvent(Id,SchoolId,CampusId,TenantId,U(now)));}
 public static string NormalizeCode(string? value){var x=value?.Trim().ToUpperInvariant()??"";if(x.Length is 0 or >50||!CodePattern().IsMatch(x))throw new DomainException("Department code must use letters, digits, hyphens, or underscores.");return x;}
 private void UpdateCore(string name,string? shortName,DepartmentType type,int order,string? headName,string? email,string? phone,string? location,string? description){if(!Enum.IsDefined(type))throw new DomainException("Department type is invalid.");if(order<0)throw new DomainException("DisplayOrder cannot be negative.");var e=Optional(email,320,nameof(Email));if(e is not null){try{_ = new MailAddress(e);}catch(FormatException){throw new DomainException("Department email is invalid.");}}Name=name;ShortName=Optional(shortName,50,nameof(ShortName));Type=type;DisplayOrder=order;HeadName=Optional(headName,200,nameof(HeadName));Email=e?.ToLowerInvariant();Phone=Optional(phone,30,nameof(Phone));Location=Optional(location,200,nameof(Location));Description=Optional(description,1000,nameof(Description));}
 private void Writable(){if(Status==DepartmentStatus.Archived)throw new DomainException("Archived departments are read-only.");} private static string Required(string? v,int max,string p){var x=v?.Trim()??"";if(x.Length==0||x.Length>max)throw new DomainException($"Department {p} is required and cannot exceed {max} characters.");return x;} private static string? Optional(string? v,int max,string p){var x=v?.Trim();if(string.IsNullOrEmpty(x))return null;if(x.Length>max)throw new DomainException($"Department {p} cannot exceed {max} characters.");return x;} private static DateTime U(DateTime x)=>x.Kind==DateTimeKind.Utc?x:x.ToUniversalTime(); [GeneratedRegex("\\A[A-Z0-9]+(?:[-_][A-Z0-9]+)*\\z")]private static partial Regex CodePattern();
}
